'use strict';
(() => {
 const catalog=window.TECHPATH_CHALLENGES;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let tab='problem',caseIndex=0,lastLesson='',expanded=false;
 function table(set){return `<div class="challenge-table"><table><thead><tr>${set.columns.map(c=>`<th>${esc(typeof c==='string'?c:c.name)}</th>`).join('')}</tr></thead><tbody>${set.rows.map(row=>`<tr>${row.map(v=>`<td${v===null?' class="is-null"':''}>${esc(v===null?'NULL':v)}</td>`).join('')}</tr>`).join('')}</tbody></table>${set.rows.length?'':'<p class="empty-result">0 dòng · result set rỗng</p>'}</div>`;}
 function schemas(p){return p.tables.map(name=>{const t=catalog.tables[name];return `<section><h3>dbo.${name}</h3><p>${esc(t.description)}</p>${table({columns:['Column','Type','Constraint'],rows:t.columns})}</section>`;}).join('')||'<p>Bài này dùng các giá trị trực tiếp, không cần bảng dữ liệu.</p>';}
 function dataset(p){return `<div class="problem-intro"><span class="eyebrow">SUPPORTLAB · SAMPLE INPUT</span><h2>Dữ liệu để suy luận</h2><p>Toàn bộ dữ liệu gốc của các bảng liên quan. Chạy SELECT trong editor để xem dữ liệu thực tế nếu bạn đã thay đổi lab.</p></div>${p.tables.map(name=>{const t=catalog.tables[name];return `<section><div class="challenge-section-head"><h3>dbo.${name}</h3><span>${t.rows.length} dòng</span></div>${table({columns:t.columns.map(c=>c[0]),rows:t.rows})}</section>`;}).join('')||'<pre class="sample-code">0.00 (VARCHAR)\n99   (INT)</pre>'}`;}
 function problem(l,d,p){return `<div class="problem-intro"><span class="eyebrow">SQL CHALLENGE · ${l.minutes} PHÚT GỢI Ý</span><h1>${esc(l.title)}</h1>${l.foundation?`<div class="foundation-step">Ôn nền ${l.foundationIndex}/20 · ${esc(l.stage)}</div>`:''}<p>${esc(p.context)}</p></div><section><h2>Yêu cầu</h2><p class="challenge-task">${esc(d.mode==='transfer'?l.transfer:l.task)}</p>${d.mode==='transfer'?'<p class="notice">Đang làm bài chuyển giao. Chấm kết quả tự động hiện chỉ hỗ trợ bài chuẩn; gia sư có thể review yêu cầu mới.</p><button class="button secondary small" data-standard>Quay về bài chuẩn</button>':''}</section><section><h2>Input Format · Cấu trúc bảng</h2>${schemas(p)}${p.tables.length>1?'<p class="relation-note">Customers 1 → nhiều Orders · Orders 1 → nhiều Payments. Lab cố ý chưa ràng buộc foreign key để có dữ liệu lỗi.</p>':''}</section><section><h2>Quy tắc & giới hạn</h2><ul>${p.rules.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><p>MS SQL Server / T-SQL. Giới hạn mỗi result set: 500 dòng; mỗi batch: 10 giây. Các bài SELECT không cần sửa dữ liệu.</p></section><section><h2>Output Format · Cần trả về</h2><p>${esc(p.output)}</p></section><section><div class="challenge-section-head"><h2>Sample Input</h2><button class="text-link" data-challenge-tab="data">Xem toàn bộ dữ liệu →</button></div><p>Dùng dataset SupportLab ở tab <strong>Dữ liệu</strong>. Các giá trị bất thường trong đó là có chủ ý.</p></section><section><h2>Sample Output</h2>${p.samples.map(table).join('')}</section><section><h2>Explanation · Giải thích ví dụ</h2><p>${esc(p.explanation)}</p></section>`;}
 function guidance(l,d){return `<div class="problem-intro"><span class="eyebrow">HỌC THEO TỪNG BƯỚC</span><h2>Khi cần một hướng đi</h2><p>Gợi ý mở dần, không tự sửa code của bạn.</p></div>${l.hints.slice(0,d.hints).map((hint,i)=>`<section><span class="eyebrow">GỢI Ý ${i+1}</span><p>${esc(hint)}</p></section>`).join('')}<button class="button secondary" data-hint ${d.hints>=l.hints.length?'disabled':''}>${d.hints>=l.hints.length?'Đã mở hết gợi ý':'Mở một gợi ý'}</button><details class="challenge-learn"><summary>Ôn kiến thức nền</summary>${l.body}</details><details id="solution"><summary>Lời giải tham khảo · có ghi nhận trợ giúp</summary>${d.solution?`<pre class="sample-code">${esc(l.solution)}</pre>`:'<p>Chỉ mở khi bạn muốn đối chiếu toàn bộ lời giải.</p><button class="button secondary" data-solution>Mở lời giải</button>'}</details><section><h3>Thử một yêu cầu khác</h3><p>${esc(l.transfer)}</p><button class="text-link" data-transfer>Chuyển sang bài chuyển giao →</button></section>`;}
 function submissions(attempts){return `<div class="problem-intro"><span class="eyebrow">SUBMISSIONS</span><h2>Lịch sử nộp bài</h2><p>Run Code không tạo lần nộp. Submit Code lưu code, kết quả và đánh giá.</p></div>${attempts.length?attempts.slice().reverse().map(a=>`<section class="submission-record"><span class="pill ${a.assessment==='sql_pass'?'green':''}">${a.assessment==='sql_pass'?'Accepted':a.judging?.verdict==='retry'?'Wrong Answer':a.assessment==='skipped'?'Đã bỏ qua':'Đã lưu'}</span><time>${esc(new Date(a.at).toLocaleString('vi-VN'))}</time><p>${esc(a.judging?.summary||a.grading?.summary||'Mốc thực hành đã lưu.')}</p><details><summary>Code tại lần nộp này</summary><pre class="sample-code">${esc(a.code)}</pre></details></section>`).join(''):'<p>Chưa có lần nộp nào. Bạn có thể chạy thử nhiều lần trước khi Submit.</p>'}`;}
 function resultPanel(run,judging){
  const result=run?.result;
  if(!result&&!judging)return `<div class="challenge-result empty-console" id="challenge-results" role="status"><span class="console-glyph">⌘</span><h3>Sẵn sàng khi bạn sẵn sàng</h3><p><strong>Run Code</strong> để xem kết quả. <strong>Submit Code</strong> để chấm và lưu bài.<br>Submit gọi model gia sư đang chọn để nhận xét ngắn; Run không gọi AI.</p></div>`;
  const judge=judging||result?.judge,cases=judge?.cases||[];
  if(caseIndex>=cases.length)caseIndex=0;
  const selected=cases[caseIndex];
  return `<section class="challenge-result" id="challenge-results" aria-label="Kết quả SQL"><div class="result-heading ${judge?.verdict==='pass'?'accepted':judge?.verdict==='retry'||result?.ok===false?'failed':''}"><div><span class="eyebrow">${judge?'SUBMISSION RESULT':'RUN RESULT'}</span><h2>${judge?.verdict==='pass'?'✓ Accepted':judge?.verdict==='retry'?'✕ Chưa đạt':judge?'◇ Cần review thêm':result.ok?'✓ Chạy thành công':'✕ SQL Error'}</h2><p>${esc(judge?.summary||result.error?.message||'Query đã chạy. Chưa ghi nhận bài nộp.')}</p></div><span class="result-time">${result?.elapsedMs||0} ms</span></div>${judge?`<p class="judge-basis">${esc(judge.basis||'')} Kết quả chỉ thuộc bản code đã nộp.</p>`:''}${cases.length?`<div class="case-layout"><nav class="case-list" aria-label="Các kiểm tra">${cases.map((c,i)=>`<button class="${i===caseIndex?'active':''} ${c.passed?'case-pass':'case-fail'}" data-challenge-case="${i}"><span>${c.passed?'✓':'✕'}</span>${esc(c.name)}</button>`).join('')}</nav><div class="case-detail"><h3>${esc(selected.name)}</h3><div class="compiler-message"><span>Thông báo</span><pre>${esc(selected.message)}</pre></div>${selected.actual?.length?`<h3>Your Output · Kết quả của bạn</h3>${selected.actual.map(table).join('')}`:''}${selected.expected?.length?`<h3>Expected Output · Kết quả cần có</h3>${selected.expected.map(table).join('')}`:''}</div></div>`:`${result?.error?`<div class="compiler-message"><span>SQL Server message${result.error.number?' · '+esc(result.error.number):''}${result.error.line?' · dòng '+esc(result.error.line):''}</span><pre>${esc(result.error.message)}</pre></div>`:''}${(result?.results||[]).map((set,i)=>`<h3>Result ${i+1} · ${set.rows.length} dòng</h3>${table(set)}`).join('')}`}${result?.truncated?'<p class="notice">Kết quả bị giới hạn. Thu hẹp query rồi chạy lại.</p>':''}${result?.messages?.length?`<details><summary>Messages</summary><pre class="sample-code">${esc(result.messages.join('\n'))}</pre></details>`:''}</section>`;
 }
 function render(l,d,info){
  if(lastLesson!==l.id){tab='problem';caseIndex=0;lastLesson=l.id;}
  const p=catalog.problems[l.id];
  return `<section class="challenge-workspace ${expanded?'is-expanded':''}"><header class="challenge-header"><div><a href="#lessons/sql">← SQL & Data Quality</a><span class="challenge-title">${esc(l.title)}</span></div><div><span class="challenge-engine">MS SQL Server</span><button class="button ghost small" data-challenge-focus>${expanded?'Thu gọn':'Mở rộng'} ⛶</button></div></header><div class="challenge-split"><article class="challenge-problem"><div class="challenge-tabs" role="tablist" aria-label="Thông tin bài"><button role="tab" aria-selected="${tab==='problem'}" data-challenge-tab="problem">Đề bài</button><button role="tab" aria-selected="${tab==='data'}" data-challenge-tab="data">Dữ liệu</button><button role="tab" aria-selected="${tab==='guide'}" data-challenge-tab="guide">Gợi ý</button><button role="tab" aria-selected="${tab==='submissions'}" data-challenge-tab="submissions">Lần nộp <span>${info.attempts.length}</span></button></div><div class="challenge-document" role="tabpanel">${info.foundationCallout||''}${tab==='problem'?problem(l,d,p):tab==='data'?dataset(p):tab==='guide'?guidance(l,d):submissions(info.attempts)}</div></article><section class="challenge-coding"><div class="editor-heading"><label for="draft-code">SQL Editor <span>T-SQL</span></label><span>● Tự lưu trên thiết bị</span></div><div class="sql-editor"><pre class="editor-gutter" aria-hidden="true"></pre><div class="editor-content"><pre class="editor-highlight" aria-hidden="true"><code></code></pre><textarea id="draft-code" class="challenge-code" aria-label="SQL Editor" autocapitalize="off" autocomplete="off" spellcheck="false" wrap="off" placeholder="-- Viết query của bạn ở đây…">${esc(d.code)}</textarea></div></div><div class="editor-status"><span>SQL Server · SupportLab</span><span id="editor-cursor">Ln 1, Col 1</span></div><div class="challenge-toolbar"><button class="button ghost small" data-new-attempt title="Lưu bản hiện tại rồi bắt đầu lần thử mới">Lần thử mới</button><div><button class="button secondary" data-stop-sql hidden>Dừng SQL</button><button class="button secondary" data-run-sql>▶ Run Code <kbd>Ctrl ↵</kbd></button><button class="button" data-submit-sql>Submit Code →</button>${info.judging?.verdict==='pass'&&!info.stale?'<button class="button secondary" data-next-lesson>Bài tiếp theo →</button>':''}</div></div><div class="challenge-console">${info.stale?'<p class="stale-result">Code đã thay đổi từ lần chạy/nộp trước. Kết quả bên dưới thuộc bản cũ; hãy chạy hoặc nộp lại.</p>':''}${resultPanel(info.run,info.judging)}<details class="challenge-tutor" ${d.notes||d.question?'open':''}><summary>Ghi chú & hỏi gia sư <span>Submit nhận xét ngắn · hỏi thêm tại đây</span></summary><label for="draft-notes">Mình đang suy luận thế nào?</label><textarea id="draft-notes" placeholder="Ghi chỗ đang bí, giả thuyết hoặc ticket của bài…">${esc(d.notes)}</textarea><label for="draft-question">Điều muốn được giải thích</label><textarea id="draft-question" placeholder="Ví dụ: Mình chưa học stored procedure. GO, AS và NOCOUNT làm gì?">${esc(d.question)}</textarea><button class="button secondary" data-ask-tutor>Hỏi gia sư về bài này ↗</button></details><textarea id="draft-output" hidden readonly>${esc(d.output)}</textarea><div class="challenge-footer"><button class="text-link" data-save-attempt>Lưu ghi chú</button><button class="text-link" data-skip>Bỏ qua bài →</button></div></div></section></div></section>`;
 }
 function highlight(code){const re=/(--[^\n]*|\/\*[\s\S]*?\*\/)|('(?:''|[^'])*')|\b(SELECT|FROM|WHERE|LEFT|RIGHT|INNER|OUTER|JOIN|ON|AND|OR|NOT|NULL|IS|AS|WITH|GROUP|BY|HAVING|ORDER|ASC|DESC|UNION|ALL|CASE|WHEN|THEN|ELSE|END|CREATE|ALTER|PROCEDURE|BEGIN|SET|NOCOUNT|EXEC|EXECUTE|GO|USE|INT|VARCHAR|NVARCHAR|DECIMAL|OVER|PARTITION|EXISTS|SUM|COUNT|COALESCE|CAST|TOP|DISTINCT)\b|\b(\d+(?:\.\d+)?)\b/gi;let last=0,out='';for(const match of code.matchAll(re)){out+=esc(code.slice(last,match.index));out+=`<span class="sql-${match[1]?'comment':match[2]?'string':match[3]?'keyword':'number'}">${esc(match[0])}</span>`;last=match.index+match[0].length;}return out+esc(code.slice(last))+'\n';}
 function mount(){
  const editor=document.querySelector('.challenge-code:not(.python-code)');if(!editor)return;
  const pre=document.querySelector('.editor-highlight'),numbers=document.querySelector('.editor-gutter');
  function cursor(){const before=editor.value.slice(0,editor.selectionStart).split('\n');document.querySelector('#editor-cursor').textContent=`Ln ${before.length}, Col ${before.at(-1).length+1}`;}
  function paint(){pre.querySelector('code').innerHTML=highlight(editor.value);numbers.textContent=Array.from({length:Math.max(12,editor.value.split('\n').length)},(_,i)=>i+1).join('\n');cursor();}
  editor.addEventListener('input',()=>{paint();const consoleArea=document.querySelector('.challenge-console');if(consoleArea&&!consoleArea.querySelector('.empty-console')&&!consoleArea.querySelector('.stale-result')){const notice=document.createElement('p');notice.className='stale-result';notice.textContent='Code đã thay đổi. Kết quả bên dưới thuộc bản cũ; hãy chạy hoặc nộp lại.';consoleArea.prepend(notice);}const next=document.querySelector('[data-next-lesson]');if(next){next.disabled=true;next.hidden=true;}});editor.addEventListener('scroll',()=>{pre.scrollTop=editor.scrollTop;pre.scrollLeft=editor.scrollLeft;numbers.scrollTop=editor.scrollTop;});editor.addEventListener('keyup',cursor);editor.addEventListener('click',cursor);paint();
 }
 window.TechPathChallenge={render,mount,tab:value=>{if(['problem','data','guide','submissions'].includes(value))tab=value;},selectCase:value=>{caseIndex=Math.max(0,Number(value)||0);},focus:()=>{expanded=!expanded;},table};
})();
